import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    idx = 0
    n = int(data[idx]); idx += 1
    k = int(data[idx]); idx += 1
    steps = [int(x) for x in data[idx:idx + k]]

    # 终局 dp: dp[0] = False (取到0颗者面对的局面为败; 等价"取走最后一颗者胜")
    # dp[i] = True 表示面对 i 颗石的玩家有必胜策略
    dp = [False] * (n + 1)
    for i in range(1, n + 1):
        for s in steps:
            if s <= i and not dp[i - s]:
                dp[i] = True
                break

    if not dp[n]:
        print("LOSE")
    else:
        # 找数值最小的必胜首取数: 取 s 后留给对手 n-s, 对手必败
        for s in sorted(steps):
            if s <= n and not dp[n - s]:
                print("WIN", s)
                return

if __name__ == "__main__":
    main()
